const getUserDetails = async (userIds) => {
  const userDetails = [];
  try {
    const usersRef = collection(db, "users");
    const userFetchPromises = userIds.map(async (userId) => {
      const userDocRef = doc(usersRef, userId);
      const userDocSnapshot = await getDoc(userDocRef);
      if (userDocSnapshot.exists()) {
        return { id: userDocSnapshot.id, ...userDocSnapshot.data() }; // Add user ID to user data
      } else {
        console.warn(`User with ID ${userId} does not exist.`);
        return null; // Return null for non-existing users
      }
    });
    const results = await Promise.all(userFetchPromises);
    userDetails.push(...results.filter((user) => user !== null));
  } catch (error) {
    console.error("Error fetching user details:", error);
  }

  return userDetails;
};

export async function createContest(formData) {
  try {
    const contestRef = doc(db, "live_quizzes", formData.quizTitle);
    const contestSnap = await getDoc(contestRef);
    if (contestSnap.exists()) {
      toast.error("Contest Id Already Exist");
      return;
    }
    const date = new Date(formData.endTime);

    await setDoc(contestRef, {
      buy: parseInt(formData.buyAmount),
      description: formData.description,
      endTime: date.getTime(),
      overall_time: parseInt(formData.duration),
      // prize: parseInt(formData.firstPrize),
      reschedule: formData.reschedule == "true" ? true : false,
      title: formData.quizTitle,
      totalPrize: parseInt(formData.totalPrizeMoney),
      totalSpots: parseInt(formData.totalSpot),
      winnings: formData.winnings,
      createdAt: serverTimestamp(),
      totalMarks: parseInt(formData.totalMarks),
      totalNoOfQuestion: parseInt(formData.totalQuestion),
      totalNoOfPayment : parseInt(0)
    });
    return true;
  } catch (error) {
    console.error("Error adding document: ", error.message);
    return false; // Return error message to indicate what went wrong
  }
}

